<?php
declare(strict_types=1);
require_once __DIR__.'/db.php';
const SESSION_TIMEOUT=1800;const AUTH_ROLES=['ADMIN','ASSOCIADO'];
function qr_secret():string{$s=trim((string)getenv('NEXUS_QR_SECRET'));if($s===''&&(getenv('APP_ENV')?:'local')!=='production')return 'local-only-nexus-qr-secret-change-before-production';if(strlen($s)<32)throw new RuntimeException('NEXUS_QR_SECRET deve ter pelo menos 32 caracteres.');return $s;}
function security_headers():void{if(headers_sent())return;header('X-Content-Type-Options: nosniff');header('X-Frame-Options: SAMEORIGIN');header('Referrer-Policy: strict-origin-when-cross-origin');header('Permissions-Policy: camera=(self), microphone=()');if(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')header('Strict-Transport-Security: max-age=31536000; includeSubDomains');}security_headers();
if(session_status()!==PHP_SESSION_ACTIVE){$secure=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off');session_set_cookie_params(['lifetime'=>0,'path'=>'/','secure'=>$secure,'httponly'=>true,'samesite'=>'Lax']);session_start();}if(empty($_SESSION['csrf_token']))$_SESSION['csrf_token']=bin2hex(random_bytes(32));
function e(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function csrf_token():string{return $_SESSION['csrf_token'];}function csrf_field():string{return '<input type="hidden" name="csrf_token" value="'.e(csrf_token()).'">';}function verify_csrf():void{if(!is_string($_POST['csrf_token']??'')||!hash_equals(csrf_token(),$_POST['csrf_token'])){http_response_code(419);exit('Token de segurança inválido.');}}
function current_user():?array{return isset($_SESSION['user'])&&is_array($_SESSION['user'])?$_SESSION['user']:null;}function is_logged_in():bool{return current_user()!==null;}
function login_limited(string $identifier):bool{global $pdo;$cut=date('Y-m-d H:i:s',time()-900);$h=hash('sha256',strtolower(trim($identifier)));$ip=hash('sha256',$_SERVER['REMOTE_ADDR']??'');$q=$pdo->prepare('SELECT COUNT(*) FROM login_attempts WHERE (identifier_hash=:id OR ip_hash=:ip) AND attempted_at>=:cut');$q->execute([':id'=>$h,':ip'=>$ip,':cut'=>$cut]);return (int)$q->fetchColumn()>=5;}function record_login_failure(string $identifier):void{global $pdo;$q=$pdo->prepare('INSERT INTO login_attempts(identifier_hash,ip_hash) VALUES(?,?)');$q->execute([hash('sha256',strtolower(trim($identifier))),hash('sha256',$_SERVER['REMOTE_ADDR']??'')]);}
function login_user(array $u):void{if(!in_array($u['perfil']??'',AUTH_ROLES,true))throw new RuntimeException('Perfil inválido.');session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$u['id'],'nome'=>(string)$u['nome'],'email'=>(string)$u['email'],'perfil'=>(string)$u['perfil'],'status_financeiro'=>(string)($u['status_financeiro']??''),'matricula'=>(string)($u['matricula']??'')];$_SESSION['last_activity']=time();}
function logout_user():void{$_SESSION=[];if(ini_get('session.use_cookies')){$p=session_get_cookie_params();setcookie(session_name(),' ',time()-42000,$p['path'],$p['domain']??'',$p['secure'],$p['httponly']);}session_destroy();}function app_url(string $p):string{$s=str_replace('\\','/',(string)($_SERVER['SCRIPT_NAME']??''));$pos=strpos($s,'/public/');$base=$pos===false?'':substr($s,0,$pos).'/public';return $base.'/'.ltrim($p,'/');}
function require_login(?string $role=null):void{$u=current_user();if(!$u||isset($_SESSION['last_activity'])&&time()-$_SESSION['last_activity']>SESSION_TIMEOUT){logout_user();header('Location: '.app_url('login.php?expired=1'));exit;}$_SESSION['last_activity']=time();if($role!==null&&($u['perfil']??'')!==$role){http_response_code(403);exit('Acesso negado.');}}function redirect_authenticated_user():never{$u=current_user();if(!$u){header('Location: '.app_url('login.php'));exit;}header('Location: '.(($u['perfil']??'')==='ADMIN'?app_url('admin/dashboard.php'):app_url('associado/carteirinha.php')));exit;}
function registrar_auditoria(int $uid,string $action,?string $table=null,?int $rid=null,mixed $old=null,mixed $new=null):void{global $pdo;$redact=function($v){if(!is_array($v))return $v;foreach(['senha','senha_hash','password','token','db_password'] as $k)if(array_key_exists($k,$v))$v[$k]='[REDACTED]';return $v;};$q=$pdo->prepare('INSERT INTO audit_logs(usuario_id,acao,tabela,registro_id,dados_antigos_json,dados_novos_json,ip_origem) VALUES(?,?,?,?,?,?,?)');$q->execute([$uid,$action,$table,$rid,$old===null?null:json_encode($redact($old),JSON_UNESCAPED_UNICODE),$new===null?null:json_encode($redact($new),JSON_UNESCAPED_UNICODE),$_SERVER['REMOTE_ADDR']??null]);}function audit(string $a,?string $t=null,?int $i=null,mixed $o=null,mixed $n=null):void{$u=current_user();registrar_auditoria((int)($u['id']??0),$a,$t,$i,$o,$n);}
